function getSearchUrl(k,t){
    const {java} = this;	  
    let baseUrl = baseApi+"/newsearch/";
    let result = "";

    switch(t) {
        //用户
    case 0:
        result = baseUrl+'blog.json?key=' + k+ '&limit=10&offset=0';
        break;

        //合集
    case 1:
        result = baseUrl+'collection.json?key=' + k+ '&limit=20&offset=0';
        break;

        //粮单
    case 2:
        result = baseUrl+'grain.json?key='+ k +'&limit=10&offset=0'
        break;

        //文章
    case 3:
        result = baseUrl+'post.json?key=' + k + '&sortType=0&offset=0&limit=20'
        break;
        //综合
     default:
        result = baseUrl+"v2/all.json?"+ver+"&sortType=0&limit=20&offset=0&version=1&key="+k
        break;
        }

        return result
}

