                 if(type === "📖") type = "collections";
                 if(type === "📗") type = "grains";
                 let s = String(source.getVariable());
                 s = /{/.test(s)?s:"";
                let jsonData = JSON.parse(s || '{"users":[],"collections":[],"grains":[],"tags":[]}');

                let existingUser = jsonData[type].find(user => String(user.id) === id);
    if (!existingUser) {
        jsonData[type].push(u);
