        feedback.textContent = '订阅成功！';
    }else{
        java.toast("订阅已存在");
        feedback.textContent = '订阅已存在！';
    }
                feedback.style.color = '#4CAF50';
                setTimeout(() => feedback.textContent = '', 2000);
            } catch(err) {
                feedback.textContent = '订阅失败';
                feedback.style.color = '#F44336';
                setTimeout(() => feedback.textContent = '', 2000);
            }
        }

        function handleCopy() {
            const content = document.getElementById('copyContent');

            // 创建范围并选择文本
            const range = document.createRange();
            range.selectNode(content);
            window.getSelection().removeAllRanges();
            window.getSelection().addRange(range);

            try {
                // 执行复制命令
                const successful = document.execCommand('copy');
                if(successful) {
                    feedback.textContent = '复制成功！';
                    feedback.style.color = '#4CAF50';
                } else {
                    feedback.textContent = '复制失败，请手动选择文本';
                    feedback.style.color = '#F44336';
                }
            } catch(err) {
                feedback.textContent = '复制错误: ' + err;
                feedback.style.color = '#F44336';
            }

            // 清除选择
            window.getSelection().removeAllRanges();

            // 3秒后隐藏反馈
            setTimeout(() => {
                feedback.textContent = '';
            }, 3000);
