const baseApi = "https://api.lofter.com";
const ver = "product=lofter-android-8.3.20";
let s = source.getVariable();
s = /{/.test(s)?s:"";
const mockData = JSON.parse(s || '{"users":[],"collections":[],"grains":[],"tags":[]}');
let startH = source.get("start");

let findItems = findItem(mockData,startH);
if(findItems.item){
      handleItemClick(findItems.type,findItems.item);	       
     if(String(source.get("isStart"))=="1"){
	        setTimeout(function() {
            window.close()
          },8) 
         }
}

// 当前数据状态
let currentData = [...mockData.users];
let currentCategory = 'user';
let remarkItemId = null;
let searchHistory = JSON.parse(source.get('lofterSearchHistory') || '[]');
let selectedItemId = null;
let isSortMode = false;


function findItem(data, startH) {
  // 检查是否是 users 中的 id
  const foundUser = data.users.find(user => user.id === startH);
  if (foundUser) {
    return { item: foundUser, type: 'user' };
  }

  // 检查是否是 collections 中的 id
  const foundCollection = data.collections.find(collection => collection.id === startH);
  if (foundCollection) {
    return { item: foundCollection, type: 'collection' };
  }

  // 检查是否是 grains 中的 id
  const foundGrain = data.grains.find(grain => grain.id === startH);
  if (foundGrain) {
    return { item: foundGrain, type: 'grain' };
  }

  // 检查是否是 tags 中的文字
  if (Array.isArray(data.tags)) {
    const foundTag = data.tags.find(tag => tag === startH);
    if (foundTag) {
      return { item: foundTag, type: 'tag' };
    }
  }

  // 如果没有找到
  return { item: null, type: null };
}

function saveDataToJson() {
    switch(currentCategory) {
        case 'user':
            mockData.users = [...currentData];
            break;
        case 'collection':
            mockData.collections = [...currentData];
            break;
        case 'grain':
            mockData.grains = [...currentData];
            break;
        case 'tag':
            mockData.tags = [...currentData];
            break;
    }
    source.putVariable(JSON.stringify(mockData));
}

//点击列表跳转对应
function handleItemClick(category, item) {
    let url,name;
    switch(category) {
        case 'user':
            run(`getUserSort("${item.name}","${item.id}");`).then(r=>java.open("sort",r));
            return;
        case 'collection':
            run(`getCollectionSort("${item.name}","${item.id}","${item.blogid}");`).then(r=>java.open("sort",r));
            return;
        case 'tag':
            run(`getTagSort("${item}");`).then(r=>java.open("sort",r));
            return;
        case 'grain':
           url = JSON.stringify({
                ["📗《"+item.name+"》"]:"https://api.lofter.com/api-grain/grain/getDetail.json?grainId="+item.id+"&offset=0"
            })
            java.open("sort", url,item.name);
            break;
    }
}

