@css:.content_left@html@js:(function(){
    var doc = org.jsoup.Jsoup.parse(result);
    var content = doc.selectFirst('.content_left');
    if (!content) return '<p>暂无内容</p>';

    // 移除无关元素
    content.select('style,script,.aggd,.kz-dtpost-div,.myshare').remove();

    // 移除隐藏付费块（常见灰色提示文本）
    var ps = content.select('p');
    for (var i = 0; i < ps.size(); i++) {
        var s = ps.get(i).attr('style') || '';
        if (s.indexOf('color:#707070') > -1) {
            ps.get(i).remove();
        }
    }

    // 精确移除包含付费关键词的元素（从后往前遍历，避免索引错乱）
    var keywords = [
        '资源下载',
        '会员下载',
        '当前隐藏内容需要支付',
        '60贝壳',
        '贝壳购买升级会员',
        '该资源没有添加描述！'
    ];
    var all = content.getAllElements();
    for (var j = all.size() - 1; j >= 0; j--) {
        var el = all.get(j);
        var own = el.ownText();
        for (var k = 0; k < keywords.length; k++) {
            if (own.indexOf(keywords[k]) > -1) {
                el.remove();
                break;
            }
        }
    }

    // 处理图片：放大、索引
    var imgs = content.select('.hig-item img');
    for (var m = 0; m < imgs.size(); m++) {
        var img = imgs.get(m);
        img.attr('style', 'display:block;margin:10px auto;max-width:100%;height:auto;cursor:zoom-in;');
        img.attr('class', 'zoom-img');
        img.attr('onclick', 'zoom(this)');
