@js:
var res;
var api = cache.get('mcs_api_url') || 'https://subocj.com/api.php/provide/vod/';
var isArt = api.indexOf('/art/') !== -1;
try {
    var d = null;
    if (typeof result === 'object') {
        d = result;
    } else if (typeof result === 'string') {
        try {
            var parsed = JSON.parse(result);
            if (parsed && parsed.list && parsed.list.length > 0) {
                d = parsed.list[0];
            }
        } catch(e) {}
    }

    if (!d) {
        res = '<div style="color:#ff5252;padding:20px;text-align:center;">暂无数据</div>';
    } else if (isArt) {
        // ========== 小说/图片模式（保持不变） ==========
        var bName = d.art_name || '未知';
        var bAuthor = d.art_author || '';
        var bType = d.type_name || '';
        var bPic = d.art_pic || '';
        var bBlurb = (d.art_blurb || '').replace(/<[^>]+>/g, '');
        var bScore = d.art_score || '';
        var bTime = d.art_time || '';
        var bId = d.art_id || '';
        var content = d.art_content || '';
        if (!content && bPic) {
            content = bPic;
        }
        var bClass = d.art_class || '';

        var isImageContent = false;
        var imageUrls = [];
        if (content) {
            var imgRegex = /https?:\/\/[^\s"'<>]+\.(jpg|jpeg|png|gif|webp)/gi;
            var imgMatches = content.match(imgRegex);
            if (imgMatches && imgMatches.length > 0) {
                isImageContent = true;
                imageUrls = imgMatches;
            }
            var imgTagRegex = /<img[^>]+src=["']([^"']+)["']/gi;
            var imgTagMatches = content.match(imgTagRegex);
            if (imgTagMatches && imgTagMatches.length > 0) {
                isImageContent = true;
                imgTagMatches.forEach(function(tag) {
                    var srcMatch = tag.match(/src=["']([^"']+)["']/i);
                    if (srcMatch && srcMatch[1]) {
                        imageUrls.push(srcMatch[1]);
                    }
                });
            }
        }

        var H = [];
        H.push('<!DOCTYPE html><html><head><meta name="viewport" content="width=device-width,initial-scale=1.0,user-scalable=no"><style>');
        H.push('*{margin:0;padding:0;box-sizing:border-box}body{background:rgba(245,245,245,var(--bg-alpha));color:#333;font-family:-apple-system,sans-serif;padding:16px;--bg-alpha:1}');
        H.push('.hdr{background:rgba(255,255,255,var(--bg-alpha));border-radius:12px;padding:16px;margin-bottom:16px;box-shadow:0 2px 8px rgba(0,0,0,.1)}');
        H.push('.meta{display:flex;gap:12px;align-items:flex-start}');
        H.push('.cover{width:100px;height:140px;border-radius:8px;object-fit:cover;background:rgba(238,238,238,var(--bg-alpha));flex-shrink:0}');
        H.push('.info{flex:1}.bn{font-size:18px;font-weight:700;color:#1a73e8;margin-bottom:8px}');
        H.push('.mt{font-size:13px;color:#666;margin:4px 0}.sc{color:#f0883e;font-weight:600}');
        H.push('.bl{font-size:13px;color:#555;line-height:1.6;margin-top:8px}');
        H.push('.content{background:rgba(255,255,255,var(--bg-alpha));border-radius:12px;padding:16px;box-shadow:0 2px 8px rgba(0,0,0,.1)}');
        H.push('.ct{font-size:18px;font-weight:700;color:#1a73e8;text-align:center;margin-bottom:16px}');
        H.push('.tx{font-size:16px;line-height:2;color:#333}.tx p{text-indent:2em;margin:8px 0}');
        H.push('.img-content img{width:100%;border-radius:8px;margin:8px 0}');
        H.push('.nav{position:fixed;bottom:0;left:0;right:0;background:rgba(255,255,255,var(--bg-alpha));border-top:1px solid rgba(238,238,238,var(--bg-alpha));display:flex;z-index:100}');
        H.push('.nav-btn{flex:1;padding:14px;text-align:center;font-size:14px;color:#1a73e8;cursor:pointer}');
        H.push('.nav-btn:active{background:rgba(248,248,248,var(--bg-alpha))}.nav-btn.disabled{color:#ccc}');
        H.push('#rd{display:none;position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(245,245,245,var(--bg-alpha));z-index:99;overflow-y:auto;padding:16px;padding-bottom:60px}');
        H.push('.ch-list{background:rgba(255,255,255,var(--bg-alpha));border-radius:12px;padding:16px;box-shadow:0 2px 8px rgba(0,0,0,.1)}');
        H.push('.ch-title{font-size:16px;font-weight:700;color:#1a73e8;margin-bottom:12px}');
        H.push('.ch-item{padding:12px;border-bottom:1px solid rgba(240,240,240,var(--bg-alpha));color:#333;cursor:pointer}');
        H.push('.ch-item:active{background:rgba(248,248,248,var(--bg-alpha))}');
        H.push('</style></head><body>');

        H.push('<div class="hdr"><div class="meta">');
        if (bPic) H.push('<img class="cover" src="' + bPic + '" onerror="this.style.display=\'none\'">');
        H.push('<div class="info"><div class="bn">' + bName + '</div>');
        if (bAuthor) H.push('<div class="mt">✍️ ' + bAuthor + '</div>');
        if (bType) H.push('<div class="mt">📁 ' + bType + '</div>');
        if (bClass) H.push('<div class="mt">🏷️ ' + bClass + '</div>');
        if (bScore) H.push('<div class="mt sc">⭐ ' + bScore + '</div>');
        if (bTime) H.push('<div class="mt">📅 ' + bTime + '</div>');
        if (bBlurb) H.push('<div class="bl">' + bBlurb.substring(0, 200) + '</div>');
        H.push('</div></div></div>');

        if (isImageContent && imageUrls.length > 0) {
            H.push('<div class="content"><div class="ct">' + bName + '</div>');
            H.push('<div class="img-content">');
            imageUrls.forEach(function(url) {
                H.push('<img src="' + url + '" loading="lazy" onerror="this.style.display=\'none\'">');
            });
            H.push('</div></div>');
        } else if (content) {
            var clean = content.replace(/<br\s*\/?>/gi, String.fromCharCode(10)).replace(/<[^>]+>/g, "").trim();
            var lines = clean.split(String.fromCharCode(10));
            var filteredLines = [];
            for (var i = 0; i < lines.length; i++) {
                var line = lines[i].trim();
                if (line.length >= 3) filteredLines.push(line);
            }
            clean = filteredLines.join(String.fromCharCode(10));
            var paragraphs = clean.split(/\n\s*\n/).filter(function(p) { return p.trim().length > 0; });
            if (paragraphs.length <= 2 && clean.length > 500) {
                paragraphs = clean.split(/\n/).filter(function(p) { return p.trim().length > 0; });
            }
            H.push('<div class="content"><div class="ct">' + bName + '</div><div class="tx">');
            paragraphs.forEach(function(p) {
                var trimmed = p.trim();
                if (trimmed.length > 0) {
                    if (trimmed.length > 200) {
                        var sentences = trimmed.split(/([。！？])/);
                        var newP = '';
                        for (var i = 0; i < sentences.length; i++) {
                            newP += sentences[i];
                            if (sentences[i] && '。！？'.indexOf(sentences[i]) >= 0) {
                                if (newP.length > 50) {
                                    H.push('<p>' + newP + '</p>');
                                    newP = '';
                                }
                            }
                        }
                        if (newP) H.push('<p>' + newP + '</p>');
                    } else {
                        H.push('<p>' + trimmed + '</p>');
                    }
                }
            });
            H.push('</div></div>');
        } else {
            H.push('<div class="content"><div class="ct">' + bName + '</div><div class="tx"><p>暂无内容</p></div></div>');
        }

        H.push('<script>');
        H.push('function applySettings(){try{var J=window.__java;if(!J||!J.get)return;var b=J.get("ft_bg")||"";var a=parseFloat(J.get("ft_alpha")||"0");if(isNaN(a))a=0;a=Math.max(0,Math.min(100,a));document.body.style.setProperty("--bg-alpha",(1-a/100).toFixed(3));if(b){document.body.style.backgroundImage="url("+b+")";document.body.style.backgroundSize="cover";document.body.style.backgroundAttachment="fixed";}else{document.body.style.backgroundImage="";document.body.style.backgroundSize="";document.body.style.backgroundAttachment="";}}catch(e){}}');
        H.push('applySettings();setInterval(applySettings,2000);');
        H.push('</script></body></html>');
        res = H.join('');
    } else {
        // ========== 影视模式 ==========
        if (!d.vod_play_url) {
            res = '<div style="color:#ff5252;padding:20px;text-align:center;">暂无播放源</div>';
        } else {
            var froms = d.vod_play_from.split('$$$');
            var urls = d.vod_play_url.split('$$$');
            var title = d.vod_name || '未知剧集';
            var cover = d.vod_pic || '';
            var year = d.vod_year || '';
            var lang = d.vod_lang || '';
            var blurb = d.vod_blurb || d.vod_content || '';

            var bgImage = '';
            var bgAlpha = '0';
            try {
                bgImage = java.get('ft_bg') || '';
                bgAlpha = java.get('ft_alpha') || '0';
            } catch(e) {}

            var html = [];
            html.push('<!DOCTYPE html><html><head><meta name="viewport" content="width=device-width,initial-scale=1.0,user-scalable=no"><style>');
            html.push('*{box-sizing:border-box;margin:0;padding:0}');
            html.push('body{background:#121212;color:#fff;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;padding:12px;--bg-alpha:1}');
            html.push('.play-wrap{max-width:800px;margin:0 auto}');
            html.push('.player-box{position:relative;width:100%;aspect-ratio:16/9;background:rgba(0,0,0,var(--bg-alpha));border-radius:12px;overflow:hidden;margin-bottom:12px;box-shadow:0 8px 22px rgba(0,0,0,.25)}');
            html.push('.player-box video{width:100%;height:100%;display:block;background:rgba(0,0,0,var(--bg-alpha))}');
            html.push('.player-loading{position:absolute;left:0;top:0;width:100%;height:100%;display:flex;align-items:center;justify-content:center;color:#ddd;background:rgba(0,0,0,calc(var(--bg-alpha)*.55));font-size:14px;z-index:2}');
            html.push('.gesture-tip{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);background:rgba(0,0,0,.7);color:#fff;padding:8px 16px;border-radius:8px;font-size:14px;z-index:10;pointer-events:none;display:none}');
            html.push('.now-playing{background:rgba(0,0,0,var(--bg-alpha));border-radius:10px;padding:10px;margin-bottom:10px;font-weight:700;color:#fff;font-size:14px;text-align:center}');
            html.push('.skip-bar{margin:10px 0;padding:10px;background:rgba(0,0,0,var(--bg-alpha));border-radius:12px;border:1px solid rgba(255,255,255,.1)}');
            html.push('.skip-title{font-size:13px;font-weight:700;color:#fff;margin-bottom:8px}');
            html.push('.skip-row{display:flex;align-items:center;gap:6px;flex-wrap:wrap}');
            html.push('.skip-row label{font-size:12px;color:#ddd}');
            html.push('.skip-row input{width:60px;padding:5px 8px;border:1px solid rgba(255,255,255,.2);border-radius:6px;font-size:13px;text-align:center;background:rgba(255,255,255,.1);color:#fff}');
            html.push('.skip-row button{background:#4f8cff;color:#fff;border:none;padding:6px 12px;border-radius:6px;font-size:13px;font-weight:700}');
            html.push('.line-tabs{display:flex;gap:8px;overflow-x:auto;padding:4px 0;margin-bottom:10px}');
            html.push('.line-tabs button{flex:0 0 auto;border:none;padding:8px 14px;border-radius:999px;background:rgba(0,0,0,var(--bg-alpha));color:#ddd;font-size:14px;font-weight:700;border:1px solid rgba(255,255,255,.1)}');
            html.push('.line-tabs button.active{background:#4f8cff;color:#fff;border-color:#4f8cff}');
            html.push('.line-panel{display:none}');
            html.push('.line-panel.active{display:block}');
            html.push('.episode-box{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}');
            html.push('.episode-box button{width:100%;padding:10px 6px;text-align:center;background:rgba(0,0,0,var(--bg-alpha));color:#eee;border-radius:12px;border:1px solid rgba(255,255,255,.1);font-size:14px;font-weight:600;box-shadow:0 2px 8px rgba(0,0,0,.2);position:relative;transition:all .15s}');
            html.push('.episode-box button.active{background:#4f8cff;color:#fff;border-color:#4f8cff}');
            html.push('.episode-box button.watched{background:rgba(79,140,255,.3);border-color:#4f8cff}');
            html.push('.episode-box button:active{transform:scale(.97)}');
            html.push('@media(max-width:360px){.episode-box{grid-template-columns:repeat(3,1fr)}}');
            html.push('.history-bar{display:flex;justify-content:flex-end;gap:8px;padding:10px 0}');
            html.push('.history-bar button{background:transparent;border:1px solid rgba(255,255,255,.2);padding:4px 10px;border-radius:6px;font-size:12px;color:#ddd}');
            html.push('.detail-box{margin-top:12px;background:rgba(0,0,0,var(--bg-alpha));border-radius:12px;padding:12px;box-shadow:0 2px 8px rgba(0,0,0,.2)}');
            html.push('.detail-top{display:flex;gap:10px;align-items:center;margin-bottom:8px}');
            html.push('.detail-top img{width:80px;height:112px;object-fit:cover;border-radius:8px;flex-shrink:0}');
            html.push('.detail-info h5{font-size:16px;font-weight:700;margin:0 0 4px;color:#fff}');
            html.push('.detail-info p{font-size:13px;color:#ccc;margin:2px 0}');
            html.push('.detail-intro{font-size:13px;color:#ddd;line-height:1.5;max-height:200px;overflow-y:auto}');
            html.push('</style></head><body>');
