@js:
var base = cache.get('mcs_api_url') || 'https://subocj.com/api.php/provide/vod/';
var isArt = base.indexOf('/art/') !== -1;
var out = [];
try {
    var json = JSON.parse(java.ajax(base + '?ac=list'));
    var cats = json.class || [];
    var ignoreIds = isArt ? [] : [1, 2, 3, 4];
    cats.forEach(function(c) {
        if (c.type_id && c.type_name) {
            if (ignoreIds.indexOf(parseInt(c.type_id, 10)) !== -1) return;
            var param = isArt ? 'list' : 'videolist';
            out.push(c.type_name + '::' + base + '?ac=' + param + '&t=' + c.type_id + '&pg=1');
        }
    });
    if (out.length === 0) out.push('暂无分类::' + base + '?ac=list&pg=1');
} catch(e) {
    out.push('加载失败::' + base + '?ac=list&pg=1');
}
out.join('\n');

