    html += "body.dark-mode{background-color:rgba(0,0,0,var(--bg-alpha));color-scheme:dark;}";
    html += "body.dark-mode .play-wrap{background:rgba(18,18,18,var(--bg-alpha));}";
    html += "body.dark-mode .now-playing{background:rgba(30,30,30,var(--bg-alpha));color:#e0e0e0;}";
    html += "body.dark-mode .line-tabs button{background:rgba(42,42,42,var(--bg-alpha));color:#e0e0e0;}";
    html += "body.dark-mode .line-tabs button.active{background:#4f8cff;color:#fff;}";
    html += "body.dark-mode .episode-box button{background:rgba(30,30,30,var(--bg-alpha));color:#e0e0e0;border-color:rgba(68,68,68,var(--bg-alpha));}";
    html += "body.dark-mode .episode-box button.active{background:#4f8cff;color:#fff;}";
    html += "body.dark-mode .episode-box button.watched{background:rgba(30,58,95,var(--bg-alpha));}";
    html += "body.dark-mode .anime-detail{background:rgba(30,30,30,var(--bg-alpha));color:#e0e0e0;}";
    html += "body.dark-mode .detail-info p{color:#ccc;}";
    html += "body.dark-mode .detail-intro{color:#bbb;}";
    html += "body.dark-mode .history-bar button{background:transparent;border-color:#444;color:#aaa;}";
    // 全屏时播放器布局调整
    html += "#playerBox:fullscreen{aspect-ratio:auto;width:100vw;height:100vh;border-radius:0;display:flex;align-items:center;justify-content:center;background:#000;}";
    html += "#playerBox:-webkit-full-screen{aspect-ratio:auto;width:100vw;height:100vh;border-radius:0;display:flex;align-items:center;justify-content:center;background:#000;}";
    html += "#playerBox:fullscreen video{width:100%;height:100%;object-fit:contain;}";
    html += "#playerBox:-webkit-full-screen video{width:100%;height:100%;object-fit:contain;}";
    html += "</style>";

    html += "<div class='play-wrap'>";
    html += "<div id='tipBar' class='tip-bar' style='display:none'></div>";

    html += "<div id='playerBox' class='player-box'>";
    html += "<div id='playerLoading' class='player-loading'>加载中...</div>";
    html += "<video id='videoPlayer' controls playsinline webkit-playsinline x5-playsinline preload='auto'></video>";
    // 已移除全屏按钮
    html += "<div id='gestureTip' class='gesture-tip'></div>";
    html += "</div>";

    html += "<div class='skip-bar'>";
    html += "<div class='skip-title'>⚙ 播放设置（仅本剧，重新进入仍生效）</div>";
    html += "<div class='skip-row'>";
    html += "<label>片头(秒)</label><input id='skipOp' type='number' min='0' step='1' placeholder='0'>";
    html += "<label>片尾(秒)</label><input id='skipEd' type='number' min='0' step='1' placeholder='0'>";
    html += "<label>速度</label><input id='speedInput' type='number' min='0.5' max='3' step='0.1' placeholder='1.0'>";
    html += "<button type='button' onclick='saveSkip()'>💾 保存</button>";
    html += "</div>";
    html += "</div>";

    html += detailBlock;

    html += "<div id='nowPlaying' class='now-playing'>正在播放：-</div>";

    html += "<div class='line-tabs'>";
    for (var t = 0; t < lines.size(); t++) {
        var tabName = String(lines.get(t).attr("id") || "").trim();
        if (tabName.length == 0) tabName = "线路" + (t + 1);
        html += "<button type='button' id='tab_" + t + "' class='" + (t == 0 ? "active" : "") + "' onclick='showLine(" + t + ")'>" + esc(tabName) + "</button>";
    }
    html += "</div>";

    for (var x = 0; x < lines.size(); x++) {
        var line = lines.get(x);
        html += "<div id='panel_" + x + "' class='line-panel " + (x == 0 ? "active" : "") + "'>";
        html += "<div class='episode-box'>";
        var episodes = line.select("a.btn-episode");
        for (var j = 0; j < episodes.size(); j++) {
            var ep = episodes.get(j);
            var title = cleanText(ep.text());
            var url = fullUrl(ep.attr("href"));
            html += "<button type='button' id='ep_" + x + "_" + j + "' data-url='" + jsEsc(url) + "' onclick=\"changePlay('" + jsEsc(url) + "','ep_" + x + "_" + j + "')\">" + esc(title) + "</button>";
        }
        html += "</div>";
        html += "</div>";
    }

    html += "<div class='history-bar'>";
    html += "<button onclick='clearHistory()'>🗑 清除本剧历史</button>";
    html += "</div>";
    html += "</div>";

    html += "<script>";
    var ftBg = java.get('ft_bg');
    if (ftBg == null) ftBg = '';
    var ftAlpha = java.get('ft_alpha');
    if (ftAlpha == null) ftAlpha = '0';

    html += "var settings = {backgroundImage: '" + jsEsc(ftBg) + "', alpha: '" + jsEsc(ftAlpha) + "'};";
    html += "document.body.style.backgroundColor='#fff';";
    html += "if(settings.backgroundImage) { document.body.style.backgroundImage = 'url(' + settings.backgroundImage + ')'; document.body.style.backgroundSize = 'cover'; document.body.style.backgroundAttachment = 'fixed'; }";
    html += "var alpha = parseFloat(settings.alpha); if(isNaN(alpha)) alpha = 0; alpha = Math.max(0, Math.min(100, alpha)); document.documentElement.style.setProperty('--bg-alpha', (1 - alpha / 100).toFixed(3));";
    html += "var playbackRate = 1;";

    html += "var firstPlayUrl='" + jsEsc(firstUrl) + "';";
    html += "var currentLine=0, currentIdx=0, currentTitle='';";
    html += "var isRestoring=false;";
    html += "function getStorageKey(){try{var p=document.location.pathname;if(p.slice(-1)=='/')p=p.slice(0,-1);if(!p)p='index';return 'acgfta_history_'+encodeURIComponent(p);}catch(e){return 'acgfta_history_default';}}";
    html += "function getHistory(){try{var d=localStorage.getItem(getStorageKey());return d?JSON.parse(d):{};}catch(e){return{};}}";
    html += "function saveHistory(){";
    html += "if(isRestoring) return;";
    html += "var h={line:currentLine, index:currentIdx, title:currentTitle, time:0};";
    html += "var video=document.getElementById('videoPlayer');";
    html += "if(video)h.time=video.currentTime||0;";
    html += "try{localStorage.setItem(getStorageKey(),JSON.stringify(h));}catch(e){}";
    html += "}";
    html += "function clearHistory(){";
    html += "localStorage.removeItem(getStorageKey());";
    html += "document.getElementById('nowPlaying').textContent='正在播放：-';";
    html += "alert('本剧历史已清除');";
    html += "}";
    html += "function updateNowPlaying(){";
    html += "var label=document.getElementById('nowPlaying');";
    html += "if(!label)return;";
    html += "var lineName='线路'+(currentLine+1);";
    html += "var tab=document.getElementById('tab_'+currentLine);";
    html += "if(tab)lineName=tab.innerText.trim();";
    html += "label.textContent='正在播放：'+lineName+' - '+(currentTitle||'未知');";
    html += "}";
    html += "function markWatched(id){";
    html += "var btn=document.getElementById(id);";
    html += "if(btn&&!btn.classList.contains('watched')){";
    html += "btn.classList.add('watched');";
    html += "}";
    html += "}";
    html += "function showLine(index){";
    html += "var tabs=document.querySelectorAll('.line-tabs button');";
    html += "var panels=document.querySelectorAll('.line-panel');";
    html += "for(var i=0;i<tabs.length;i++){tabs[i].classList.remove('active');}";
    html += "for(var j=0;j<panels.length;j++){panels[j].classList.remove('active');}";
    html += "document.getElementById('tab_'+index).classList.add('active');";
    html += "document.getElementById('panel_'+index).classList.add('active');";
    html += "}";
    html += "function setActive(id){";
    html += "var eps=document.querySelectorAll('.episode-box button');";
    html += "for(var i=0;i<eps.length;i++){eps[i].classList.remove('active');}";
    html += "var now=document.getElementById(id);";
    html += "if(now){now.classList.add('active');markWatched(id);}";
    html += "}";
    html += "function getM3u8FromText(txt){";
    html += "var m=txt.match(/var\\s+player_aaaa\\s*=\\s*(\\{[\\s\\S]*?\\})<\\/script>/);";
    html += "if(!m){m=txt.match(/var\\s+player_aaaa\\s*=\\s*(\\{[\\s\\S]*?\\})/);}";
    html += "if(m){";
    html += "try{";
    html += "var obj=JSON.parse(m[1]);";
    html += "if(obj&&obj.url)return obj.url;";
    html += "}catch(e){";
    html += "var u=m[1].match(/\"url\"\\s*:\\s*\"([^\"]+)\"/);";
    html += "if(u)return u[1].replace(/\\\\\\//g,'/');";
    html += "}";
    html += "}";
    html += "var nuxt=txt.match(/__NUXT__\\s*=\\s*(\\{[\\s\\S]*?\\});?\\s*<\\/script>/);";
    html += "if(nuxt){";
    html += "try{";
    html += "var data=JSON.parse(nuxt[1]);";
    html += "var state=data.state||data;";
    html += "if(state.player_aaaa&&state.player_aaaa.url)return state.player_aaaa.url;";
    html += "}catch(e){}";
    html += "}";
    html += "var direct=txt.match(/https?:\\/\\/[^\\s\"']+\\.m3u8[^\\s\"']*/i);";
    html += "return direct ? direct[0] : '';";
    html += "}";
    html += "function playM3u8(m3u8){";
    html += "var video=document.getElementById('videoPlayer');";
    html += "var loading=document.getElementById('playerLoading');";
    html += "if(!m3u8){loading.innerHTML='未获取到播放地址';return;}";
    html += "loading.style.display='none';";
    html += "if(window.Hls && Hls.isSupported()){";
    html += "  if(video._hls) video._hls.destroy();";
    html += "  var hls=new Hls();";
    html += "  video._hls=hls;";
    html += "  hls.loadSource(m3u8);";
    html += "  hls.attachMedia(video);";
    html += "  hls.on(Hls.Events.MANIFEST_PARSED,function(){video.playbackRate = playbackRate; video.play().catch(function(){});});";
    html += "  hls.on(Hls.Events.ERROR,function(event,data){if(data.fatal){loading.style.display='flex';loading.innerHTML='播放失败：'+data.type;}});";
    html += "} else if(video.canPlayType('application/vnd.apple.mpegurl')){";
    html += "  video.src=m3u8;";
    html += "  video.addEventListener('loadedmetadata',function(){video.playbackRate = playbackRate; video.play().catch(function(){});});";
    html += "} else {";
    html += "  loading.style.display='flex';";
    html += "  loading.innerHTML='当前环境不支持HLS播放';";
    html += "}";
    html += "}";
    html += "function changePlay(playUrl,id){";
    html += "if(!isRestoring) saveHistory();";
    html += "setActive(id);";
    html += "var parts=id.split('_');";
    html += "if(parts.length===3){";
    html += "  currentLine=parseInt(parts[1]);";
    html += "  currentIdx=parseInt(parts[2]);";
    html += "}";
    html += "var btn=document.getElementById(id);";
    html += "currentTitle=btn?btn.innerText.trim():'';";
    html += "updateNowPlaying();";
    html += "var loading=document.getElementById('playerLoading');";
    html += "loading.style.display='flex';";
    html += "loading.innerHTML='加载中...';";
    html += "fetch(playUrl, {headers: {'Referer': 'https://acgfta.com/'}}).then(function(res){return res.text();}).then(function(txt){";
    html += "var m3u8=getM3u8FromText(txt);";
    html += "playM3u8(m3u8);";
    html += "saveHistory();";
    html += "}).catch(function(err){";
    html += "loading.innerHTML='请求失败：'+err.message;";
    html += "});";
    html += "window.scrollTo(0,0);";
    html += "}";
    html += "var video=document.getElementById('videoPlayer');";
    html += "video.addEventListener('timeupdate',function(){";
    html += "if(video.currentTime && !isRestoring) saveHistory();";
    html += "});";
    html += "function restoreHistory(){";
    html += "var h=getHistory();";
    html += "if(!h.line && h.line!==0)return false;";
    html += "isRestoring=true;";
    html += "showLine(h.line);";
    html += "var histId='ep_'+h.line+'_'+h.index;";
    html += "var btn=document.getElementById(histId);";
    html += "if(btn){";
    html += "  changePlay(btn.getAttribute('data-url'), histId);";
    html += "  var vid=document.getElementById('videoPlayer');";
    html += "  if(h.time && vid){";
    html += "    vid.addEventListener('loadedmetadata',function(){";
    html += "      this.currentTime=h.time;";
    html += "    }, {once: true});";
    html += "  }";
    html += "  isRestoring=false;";
    html += "  return true;";
    html += "}";
    html += "isRestoring=false;";
    html += "return false;";
    html += "}";
    html += "setTimeout(function(){";
    html += "  if(!restoreHistory()) changePlay(firstPlayUrl,'ep_0_0');";
    html += "}, 100);";
    html += "var J=(typeof window.__java!=='undefined')?window.__java:null;";
    html += "function showTip(t){var b=document.getElementById('tipBar');if(!b)return;b.textContent=t;b.style.display='block';clearTimeout(b._t);b._t=setTimeout(function(){b.style.display='none';},3500);}";
    html += "function applySettings(){";
    html += "try{";
    html += "if(!J||!J.get)return;";
    html += "var msg=J.get('ft_msg');";
    html += "if(msg){J.toast(msg);showTip(msg);J.put('ft_msg','');}";
    html += "var b=J.get('ft_bg')||'';";
    html += "var a=parseFloat(J.get('ft_alpha')||'0');if(isNaN(a))a=0;a=Math.max(0,Math.min(100,a));";
    html += "document.documentElement.style.setProperty('--bg-alpha',(1-a/100).toFixed(3));";
    html += "document.body.style.backgroundColor='#fff';";
    html += "if(b){document.body.style.backgroundImage='url('+b+')';document.body.style.backgroundSize='cover';document.body.style.backgroundAttachment='fixed';}else{document.body.style.backgroundImage='';document.body.style.backgroundSize='';document.body.style.backgroundAttachment='';}";
    html += "}catch(e){}";
    html += "}";
    html += "setInterval(applySettings,2000);";
    html += "document.addEventListener('visibilitychange',function(){if(!document.hidden)applySettings();});";
    html += "var skipOp=0,skipEd=0;";
    html += "function loadSkip(){try{var d=localStorage.getItem(getStorageKey()+'_skip');if(d){var o=JSON.parse(d);skipOp=parseInt(o.op)||0;skipEd=parseInt(o.ed)||0;var sp=parseFloat(o.speed);if(!(sp>0))sp=1;playbackRate=sp;var v=document.getElementById('videoPlayer');if(v)v.playbackRate=sp;var io=document.getElementById('skipOp'),ie=document.getElementById('skipEd'),is=document.getElementById('speedInput');if(io)io.value=skipOp||'';if(ie)ie.value=skipEd||'';if(is)is.value=sp===1?'':sp;}}catch(e){}}";
    html += "function saveSkip(){var io=document.getElementById('skipOp'),ie=document.getElementById('skipEd'),is=document.getElementById('speedInput');var op=io?(parseInt(io.value)||0):0,ed=ie?(parseInt(ie.value)||0):0,sp=is?parseFloat(is.value):1;if(op<0)op=0;if(ed<0)ed=0;if(!(sp>0)||isNaN(sp))sp=1;skipOp=op;skipEd=ed;playbackRate=sp;var v=document.getElementById('videoPlayer');if(v)v.playbackRate=sp;try{localStorage.setItem(getStorageKey()+'_skip',JSON.stringify({op:op,ed:ed,speed:sp}));}catch(e){}showTip('⏭ 已保存：片头 '+op+' 秒 / 片尾 '+ed+' 秒 / 速度 '+sp+'x');}";
    html += "function skipCheck(){var v=document.getElementById('videoPlayer');if(!v||!v.duration||!isFinite(v.duration))return;try{if(skipOp>0&&v.currentTime<skipOp&&!v.seeking){v.currentTime=skipOp;}if(skipEd>0&&v.currentTime>=v.duration-skipEd&&v.currentTime<v.duration){v.currentTime=v.duration;}}catch(e){}}";
    html += "var vp=document.getElementById('videoPlayer');vp.addEventListener('timeupdate',skipCheck);";
    html += "loadSkip();";
    // 已移除 toggleFullscreen 函数，保留自动横屏逻辑
    html += "function lockLandscape(){if(screen.orientation&&screen.orientation.lock){screen.orientation.lock('landscape').catch(function(){});}}";
    html += "function unlockOrientation(){if(screen.orientation&&screen.orientation.unlock){screen.orientation.unlock();}}";
    html += "document.addEventListener('fullscreenchange',function(){if(document.fullscreenElement){lockLandscape();}else{unlockOrientation();}});";
    html += "document.addEventListener('webkitfullscreenchange',function(){if(document.webkitFullscreenElement){lockLandscape();}else{unlockOrientation();}});";
    // 手势功能
    html += "var gestureTip=document.getElementById('gestureTip');";
    html += "var startX=0,startY=0,seekStartTime=0,pendingSeekDelta=0;";
    html += "var longPressTimer=null,longPressTriggered=false,tempRateActive=false,originalRate=1;";
    html += "function formatTime(sec){if(!isFinite(sec)||sec<0)sec=0;var m=Math.floor(sec/60),s=Math.floor(sec%60);return (m<10?'0'+m:m)+':'+(s<10?'0'+s:s);}";
    html += "function showGestureTip(msg){gestureTip.textContent=msg;gestureTip.style.display='block';}";
    html += "function hideGestureTip(){gestureTip.style.display='none';}";
    html += "document.addEventListener('touchstart',function(e){if(e.target!==vp&&e.target!==document.getElementById('playerBox'))return;if(e.touches.length!==1)return;startX=e.touches[0].clientX;startY=e.touches[0].clientY;seekStartTime=vp.currentTime||0;pendingSeekDelta=0;longPressTriggered=false;tempRateActive=false;clearTimeout(longPressTimer);longPressTimer=setTimeout(function(){longPressTriggered=true;tempRateActive=true;originalRate=playbackRate;playbackRate=Math.min(3,playbackRate+0.5);vp.playbackRate=playbackRate;showGestureTip('临时速度 '+playbackRate.toFixed(1)+'x，上下滑调整');},500);});";
    html += "document.addEventListener('touchmove',function(e){if(e.target!==vp&&e.target!==document.getElementById('playerBox'))return;if(e.touches.length!==1)return;var dx=e.touches[0].clientX-startX;var dy=e.touches[0].clientY-startY;if(longPressTriggered){if(Math.abs(dy)>Math.abs(dx)){var delta=-dy;var steps=Math.round(delta/30);if(steps!==0){var newRate=playbackRate+steps*0.1;newRate=Math.max(0.5,Math.min(3,newRate));newRate=Math.round(newRate*10)/10;if(newRate!==playbackRate){playbackRate=newRate;vp.playbackRate=playbackRate;showGestureTip('临时速度 '+playbackRate.toFixed(1)+'x');}}}}else{if(Math.abs(dx)>Math.abs(dy)&&isFinite(vp.duration)){pendingSeekDelta=dx/10;var target=seekStartTime+pendingSeekDelta;target=Math.max(0,Math.min(vp.duration,target));showGestureTip('进度 '+formatTime(target)+' / '+formatTime(vp.duration));}}});";
    html += "document.addEventListener('touchend',function(e){if(e.target!==vp&&e.target!==document.getElementById('playerBox'))return;clearTimeout(longPressTimer);if(tempRateActive){playbackRate=originalRate;vp.playbackRate=playbackRate;showGestureTip('已恢复速度 '+playbackRate.toFixed(1)+'x');tempRateActive=false;longPressTriggered=false;setTimeout(hideGestureTip,500);}else{if(pendingSeekDelta!==0&&isFinite(vp.duration)){var target=seekStartTime+pendingSeekDelta;target=Math.max(0,Math.min(vp.duration,target));vp.currentTime=target;}longPressTriggered=false;pendingSeekDelta=0;hideGestureTip();}});";
    html += "</script>";

    html;
}

