@js:
(function(){
    try {
        var data = JSON.parse(result);
        var videoId = data.video.id; 
        var videoName = data.video.name;
        var playlists = data.video.playlists;
        var labels = data.player_label_arr;
        var cover = data.video.cover;
        var jxUrl = "https://jx.ejtsyc.com:8443/m3u8/?url=";

        // 详情字段
        var year = data.video.year || '';
        var area = data.video.area || '';
        var status = data.video.status || '';
        var type = data.video.type || '';
        var tags = data.video.tags || '';
        var writer = data.video.writer || '';
        var company = data.video.company || '';
        var intro = data.video.intro_clean || data.video.intro || '暂无简介';

        function esc(s) {
            return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
        }

        // 默认播放链接
        var defaultPlayUrl = "";
        for (var k in playlists) {
            if (playlists[k] && playlists[k].length > 0) {
                defaultPlayUrl = jxUrl + playlists[k][0][1];
                break;
            }
        }

        // 构建 HTML
        var html = '<!DOCTYPE html><html><head>';
        html += '<meta charset="UTF-8">';
        html += '<meta name="viewport" content="width=device-width, initial-scale=1.0">';
        html += '<meta name="referrer" content="never">';
        html += '<title>' + esc(videoName) + '</title>';
        html += '</head><body style="margin:0; padding:8px; font-family: sans-serif;">';
        html += '<div style="width:100%;">';

        // 播放器（包裹一层div以便全屏）
        html += '<div id="player-wrapper" style="position:relative; width:100%;">';
        if (defaultPlayUrl !== "") {
            html += '<iframe name="ageplayer" id="ageplayer" src="' + defaultPlayUrl + '" width="100%" height="240px" frameborder="0" allowfullscreen="true" style="border-radius:8px; background:#000;"></iframe>';
        } else {
            html += '<img src="' + esc(cover) + '" style="width:100%; border-radius:8px;"/>';
        }
        html += '</div>';

        // 详情卡片（播放器下方）
        html += '<div style="display:flex; gap:10px; margin:12px 0; align-items:flex-start;">';
        html += '<img src="' + esc(cover) + '" style="width:80px; height:112px; object-fit:cover; border-radius:8px; flex-shrink:0;" onerror="this.style.display=\'none\'">';
        html += '<div style="flex:1; min-width:0;">';
        html += '<div style="font-weight:bold; font-size:16px; margin-bottom:4px;">' + esc(videoName) + '</div>';
        var detailArr = [];
        if (year) detailArr.push('年份：' + year);
        if (area) detailArr.push('地区：' + area);
        if (status) detailArr.push('状态：' + status);
        if (type) detailArr.push('类型：' + type);
        if (tags) detailArr.push('标签：' + tags);
        if (detailArr.length) html += '<div style="font-size:13px; color:#666; margin-bottom:2px;">' + esc(detailArr.join('　')) + '</div>';
        if (writer) html += '<div style="font-size:13px; color:#666;">编剧：' + esc(writer) + '</div>';
        if (company) html += '<div style="font-size:13px; color:#666;">制作：' + esc(company) + '</div>';
        html += '<div style="font-size:13px; color:#888; margin-top:6px; line-height:1.5; max-height:90px; overflow:auto;">' + esc(intro) + '</div>';
        html += '</div></div>';

        // 历史提示 + 清除按钮
        html += '<div style="display:flex; justify-content:space-between; align-items:center; margin-top:12px;">';
        html += '<p id="history-text" style="color:#f60; font-size:14px; font-weight:bold; text-align:center; flex:1; margin:0;">读取进度中...</p>';
        html += '<button onclick="clearHistory()" style="background:none; border:1px solid #ddd; padding:4px 10px; border-radius:6px; color:#999; font-size:12px;">清除历史</button>';
        html += '</div>';

        // 线路 tabs 和剧集容器
        var tabsHtml = '<div style="display:flex; overflow-x:auto; gap:15px; border-bottom:1px solid #eee; padding-bottom:8px; margin-top:10px; white-space:nowrap; -webkit-overflow-scrolling: touch;">';
        var epsHtml = '<div style="margin-top:15px;">';
        var tabIndex = 0;
        var firstTabId = "";
        var firstLineName = "";
        var firstEpName = "";

        for (var key in playlists) {
            var lineName = labels[key] ? labels[key] : key;
            var tId = "line_" + tabIndex;
            var episodes = playlists[key];
            if (tabIndex === 0) {
                firstTabId = tId;
                firstLineName = lineName;
                if (episodes.length > 0) firstEpName = episodes[0][0];
            }
            tabsHtml += '<div id="tab_' + tId + '" class="line-tab" onclick="switchTab(\'' + tId + '\')" style="padding:4px 8px; color:#666; font-size:15px; cursor:pointer; transition:all 0.2s;">' + lineName + '</div>';
            epsHtml += '<div id="container_' + tId + '" class="ep-container" style="display:none; flex-wrap:wrap; gap:10px;">';
            for (var i = 0; i < episodes.length; i++) {
                var epName = episodes[i][0];
                var epCode = episodes[i][1];
                var playUrl = jxUrl + epCode;
                epsHtml += '<a href="' + playUrl + '" target="ageplayer" class="ep-btn" onclick="savePlayHistory(this, \'' + playUrl + '\', \'' + lineName + '\', \'' + epName + '\', \'' + tId + '\', ' + tabIndex + ', ' + i + ')" style="padding:6px 12px; background:#f0f2f5; text-decoration:none; color:#333; border-radius:6px; font-size:14px; border:1px solid #e4e6eb; text-align:center; transition: all 0.2s;">' + epName + '</a>';
            }
            epsHtml += '</div>';
            tabIndex++;
        }
        tabsHtml += '</div>';
        epsHtml += '</div>';

        html += tabsHtml;
        html += epsHtml;
        html += '</div></body>';

        // 注入 JS
        html += '<script>';
        html += 'var storageKey = "age_history_" + ' + JSON.stringify(videoId || encodeURIComponent(videoName)) + ';';
        html += 'function switchTab(tId) {';
        html += '  var eps = document.querySelectorAll(".ep-container");';
        html += '  for(var i=0; i<eps.length; i++) eps[i].style.display = "none";'; 
        html += '  var tabs = document.querySelectorAll(".line-tab");';
        html += '  for(var i=0; i<tabs.length; i++) { tabs[i].style.color = "#666"; tabs[i].style.borderBottom = "none"; tabs[i].style.fontWeight = "normal"; }'; 
        html += '  document.getElementById("container_" + tId).style.display = "flex";'; 
        html += '  var activeTab = document.getElementById("tab_" + tId);';
        html += '  if(activeTab) { activeTab.style.color = "#f60"; activeTab.style.borderBottom = "2px solid #f60"; activeTab.style.fontWeight = "bold"; }'; 
        html += '}';

        html += 'function savePlayHistory(btnElem, url, lineName, epName, tId, lineIndex, epIndex) {';
        html += '  var histText = lineName + " - " + epName;';
        html += '  var saveData = {';
        html += '    url: url,';
        html += '    lineName: lineName,';
        html += '    epName: epName,';
        html += '    tabId: tId,';
        html += '    lineIndex: lineIndex,';
        html += '    epIndex: epIndex,';
        html += '    timestamp: Date.now()';
        html += '  };';
        html += '  localStorage.setItem(storageKey, JSON.stringify(saveData));';
        html += '  var timeStr = new Date(saveData.timestamp).toLocaleString("zh-CN", {hour12:false});';
        html += '  document.getElementById("history-text").innerText = "上次观看：" + histText + "（" + timeStr + "）";';
        html += '  var btns = document.querySelectorAll(".ep-btn");';
        html += '  for(var i=0; i<btns.length; i++){ btns[i].style.background="#f0f2f5"; btns[i].style.color="#333"; btns[i].style.borderColor="#e4e6eb"; }';
        html += '  btnElem.style.background="#f60"; btnElem.style.color="#fff"; btnElem.style.borderColor="#f60";';
        html += '}';

        html += 'function clearHistory() {';
        html += '  localStorage.removeItem(storageKey);';
        html += '  var player = document.getElementById("ageplayer");';
        html += '  if(player) player.src = "' + defaultPlayUrl + '";';
        html += '  switchTab("' + firstTabId + '");';
        html += '  document.getElementById("history-text").innerText = "已清除历史，请重新选择剧集";';
        html += '  var btns = document.querySelectorAll(".ep-btn");';
        html += '  for(var i=0; i<btns.length; i++){ btns[i].style.background="#f0f2f5"; btns[i].style.color="#333"; btns[i].style.borderColor="#e4e6eb"; }';
        html += '  var firstBtn = document.querySelector("#container_' + firstTabId + ' .ep-btn");';
        html += '  if(firstBtn) { firstBtn.style.background="#f60"; firstBtn.style.color="#fff"; firstBtn.style.borderColor="#f60"; }';
        html += '}';

        html += 'window.onload = function() {';
        html += '  var savedStr = localStorage.getItem(storageKey);';
        html += '  if (savedStr) {';
        html += '    try {';
        html += '      var savedData = JSON.parse(savedStr);';
        html += '      var targetBtn = null;';
        html += '      if (savedData.lineIndex !== undefined && savedData.epIndex !== undefined) {';
        html += '        var container = document.getElementById("container_line_" + savedData.lineIndex);';
        html += '        if (container) {';
        html += '          var allBtns = container.querySelectorAll(".ep-btn");';
        html += '          if (savedData.epIndex < allBtns.length) targetBtn = allBtns[savedData.epIndex];';
        html += '        }';
        html += '      }';
        html += '      if (!targetBtn && savedData.url) {';
        html += '        var btns = document.querySelectorAll(".ep-btn");';
        html += '        for(var i=0; i<btns.length; i++){';
        html += '          if(btns[i].getAttribute("href") === savedData.url) { targetBtn = btns[i]; break; }';
        html += '        }';
        html += '      }';
        html += '      if (targetBtn) {';
        html += '        if (savedData.tabId) switchTab(savedData.tabId);';
        html += '        document.getElementById("ageplayer").src = targetBtn.getAttribute("href");';
        html += '        var timeStr = savedData.timestamp ? new Date(savedData.timestamp).toLocaleString("zh-CN", {hour12:false}) : "";';
        html += '        var histText = savedData.lineName + " - " + savedData.epName;';
        html += '        document.getElementById("history-text").innerText = "上次观看：" + histText + (timeStr ? "（" + timeStr + "）" : "");';
        html += '        var allBtns = document.querySelectorAll(".ep-btn");';
        html += '        for(var i=0; i<allBtns.length; i++){ allBtns[i].style.background="#f0f2f5"; allBtns[i].style.color="#333"; allBtns[i].style.borderColor="#e4e6eb"; }';
        html += '        targetBtn.style.background="#f60"; targetBtn.style.color="#fff"; targetBtn.style.borderColor="#f60";';
        html += '      } else {';
        html += '        switchTab("' + firstTabId + '");';
        html += '        document.getElementById("history-text").innerText = "您当前已观看到：' + firstLineName + ' - ' + firstEpName + '";';
        html += '        var firstBtn = document.querySelector("#container_' + firstTabId + ' .ep-btn");';
        html += '        if(firstBtn) { firstBtn.style.background="#f60"; firstBtn.style.color="#fff"; firstBtn.style.borderColor="#f60"; }';
        html += '      }';
        html += '    } catch(e) {';
        html += '      switchTab("' + firstTabId + '");';
        html += '      document.getElementById("history-text").innerText = "您当前已观看到：' + firstLineName + ' - ' + firstEpName + '";';
        html += '      var firstBtn = document.querySelector("#container_' + firstTabId + ' .ep-btn");';
        html += '      if(firstBtn) { firstBtn.style.background="#f60"; firstBtn.style.color="#fff"; firstBtn.style.borderColor="#f60"; }';
        html += '    }';
        html += '  } else {';
        html += '    switchTab("' + firstTabId + '");';
        html += '    document.getElementById("history-text").innerText = "您当前已观看到：' + firstLineName + ' - ' + firstEpName + '";';
        html += '    var firstBtn = document.querySelector("#container_' + firstTabId + ' .ep-btn");';
        html += '    if(firstBtn) { firstBtn.style.background="#f60"; firstBtn.style.color="#fff"; firstBtn.style.borderColor="#f60"; }';
        html += '  }';
        html += '};';

        // ===== 新增：全屏自动横屏 =====
        html += 'function lockLandscape(){if(screen.orientation&&screen.orientation.lock){screen.orientation.lock("landscape").catch(function(){});}}';
        html += 'function unlockOrientation(){if(screen.orientation&&screen.orientation.unlock){screen.orientation.unlock();}}';
        html += 'document.addEventListener("fullscreenchange",function(){if(document.fullscreenElement){lockLandscape();}else{unlockOrientation();}});';
        html += 'document.addEventListener("webkitfullscreenchange",function(){if(document.webkitFullscreenElement){lockLandscape();}else{unlockOrientation();}});';

        html += '</script></html>';

        return html;
    } catch(e) {
        return "解析错误：" + e.message;
    }
})();

